                    /* Would exceed buffer, free buffer and return failure */
                    free(ctx->temp_buffer);
                    ctx->temp_buffer = NULL;
                    ctx->buffer_size = 0;
                    return -1;
                }

                memset(ctx->temp_buffer + dst_idx, value, count);
                dst_idx += count;
            }

            if (dst_idx != expected_size) {
                /* Decompressed size mismatch, free buffer and return failure */
                free(ctx->temp_buffer);
                ctx->temp_buffer = NULL;
                ctx->buffer_size = 0;
                return -1;
            }
            break;
        }
        default: {
            /* Unsupported compression type, free buffer and return failure */
            free(ctx->temp_buffer);
            ctx->temp_buffer = NULL;
            ctx->buffer_size = 0;
            return -1;
        }
    }

    /* Stage 3: Integrity Verification */
    checksum_calculated = 0;
    for (size_t i = 0; i < expected_size; i++) {
        checksum_calculated = (unsigned char)(checksum_calculated + ctx->temp_buffer[i]);
    }

    if (checksum_calculated != checksum_stored) {
        /* Checksum mismatch, free buffer and return failure */
        free(ctx->temp_buffer);
        ctx->temp_buffer = NULL;
        ctx->buffer_size = 0;
        return -1;
    }

    /* Success: ctx->temp_buffer contains decompressed data, caller must free it */
    return 0;
}
